def apply(admin1: dict) -> tuple[int, int]:
    n_specific = n_default = 0
    for sid, rec in admin1.items():
        iso = rec.get("iso3")
        if iso not in KNOWLEDGE:
            continue
        lname = rec.get("name", "").lower()
        note = None
        for pat, nt in KNOWLEDGE[iso]:
            if pat and pat in lname:
                note = nt
                break
        if note:
            rec["modelContext"] = note
            n_specific += 1
        else:
            rec["modelContext"] = DEFAULT_NOTE
            n_default += 1
    return n_specific, n_default


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--admin1-file", default=str(ROOT / "data" / "admin1.json"))
    args = ap.parse_args()

    p = Path(args.admin1_file)
    admin1 = json.loads(p.read_text(encoding="utf-8"))
    n_specific, n_default = apply(admin1)
    print(f"modelContext written: {n_specific} specific · {n_default} default · "
          f"{len(KNOWLEDGE)} country tables")
    if args.dry_run:
        return 0
    tmp = p.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(admin1, indent=1, ensure_ascii=False), encoding="utf-8")
    tmp.replace(p)
    print(f"wrote {p}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
